import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';

export interface AuthUser {
  email: string;
  name: string;
  role: string;
  office: string;
  securityLevel: string;
  loginTimestamp: string;
}

interface AuthContextType {
  user: AuthUser | null;
  isAuthenticated: boolean;
  pendingMfaEmail: string | null;
  login: (email: string, password: string) => { success: boolean; error?: string; requireMfa?: boolean };
  verifyMfa: (code: string) => { success: boolean; error?: string };
  cancelMfa: () => void;
  logout: () => void;
}

const AUTH_STORAGE_KEY = 'mantova_auth_session_v1';

export const VALID_CREDENTIALS = {
  email: 'admin@mantova.mn.it',
  password: 'Av3ng3r$',
  mfaCode: '123456',
};

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<AuthUser | null>(() => {
    try {
      const saved = localStorage.getItem(AUTH_STORAGE_KEY);
      if (saved) {
        return JSON.parse(saved);
      }
    } catch (e) {
      console.warn('Errore lettura sessione autenticata', e);
    }
    return null;
  });

  const [pendingMfaEmail, setPendingMfaEmail] = useState<string | null>(null);

  useEffect(() => {
    try {
      if (user) {
        localStorage.setItem(AUTH_STORAGE_KEY, JSON.stringify(user));
      } else {
        localStorage.removeItem(AUTH_STORAGE_KEY);
      }
    } catch (e) {
      console.warn('Errore salvataggio sessione auth', e);
    }
  }, [user]);

  const login = (email: string, password: string) => {
    const cleanEmail = email.trim().toLowerCase();
    const cleanPass = password.trim();

    if (cleanEmail === VALID_CREDENTIALS.email.toLowerCase() && cleanPass === VALID_CREDENTIALS.password) {
      setPendingMfaEmail(cleanEmail);
      return { success: true, requireMfa: true };
    }

    return {
      success: false,
      error: 'Credenziali non valide. Verificare indirizzo email istituzionale e password di accesso.'
    };
  };

  const verifyMfa = (code: string) => {
    const cleanCode = code.trim().replace(/\s/g, '');

    if (cleanCode === VALID_CREDENTIALS.mfaCode) {
      const authenticatedUser: AuthUser = {
        email: VALID_CREDENTIALS.email,
        name: 'Amministratore di Sistema DUP',
        role: 'Responsabile Control Room Strategica & DUP',
        office: 'Comune di Mantova — Ufficio di Staff RTD / Giunta',
        securityLevel: 'SPID / CIE Livello 3 (MFA Hardware/TOTP)',
        loginTimestamp: new Date().toISOString()
      };
      setUser(authenticatedUser);
      setPendingMfaEmail(null);
      return { success: true };
    }

    return {
      success: false,
      error: 'Codice di sicurezza MFA errato. Inserire il codice OTP a 6 cifre valido.'
    };
  };

  const cancelMfa = () => {
    setPendingMfaEmail(null);
  };

  const logout = () => {
    setUser(null);
    setPendingMfaEmail(null);
    try {
      localStorage.removeItem(AUTH_STORAGE_KEY);
    } catch {
      // ignore
    }
  };

  return (
    <AuthContext.Provider
      value={{
        user,
        isAuthenticated: !!user,
        pendingMfaEmail,
        login,
        verifyMfa,
        cancelMfa,
        logout
      }}
    >
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = (): AuthContextType => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth deve essere utilizzato all’interno di un AuthProvider');
  }
  return context;
};
