import React, { useState } from 'react';
import {
  RefreshCw,
  ArrowRight,
  CheckCircle2,
  FileText,
  BadgeCheck,
  Globe,
  SlidersHorizontal,
  Clock,
  UserCheck,
  History,
  AlertCircle,
  FileCheck2,
  Calendar
} from 'lucide-react';
import { useData } from '../../store/DataContext';
import { DataVerificationStage } from '../../types';
import { DataStageBadge } from '../../components/common/StatusBadge';
import { formatDate } from '../../utils';

export const MonitoringWorkflowView: React.FC = () => {
  const { data, updateKPI, searchQuery } = useData();
  const [selectedFilterStage, setSelectedFilterStage] = useState<string>('all');
  const [editingKpiId, setEditingKpiId] = useState<string | null>(null);

  const workflowSteps = [
    { number: '1', title: 'ASTER / UFFICI OPERATIVI', desc: 'Rilevazione sul campo e raccolta evidenze primarie' },
    { number: '2', title: 'RACCOLTA & SCHEDATURA', desc: 'Immissione valori periodici dichiarati' },
    { number: '3', title: 'VERIFICA TECNICA', desc: 'Controllo di congruità metodologica (RTD / CDG)' },
    { number: '4', title: 'AGGIORNAMENTO KPI', desc: 'Ricalcolo formule, target e percentuali' },
    { number: '5', title: 'REPORT DIREZIONALE', desc: 'Consolidamento per la Cabina di Regia e Giunta' },
    { number: '6', title: 'VALUTAZIONE & AZIONI', desc: 'Decisioni politiche e rimodulazione interventi' }
  ];

  const handleStageAdvance = (kpiId: string, currentStage: DataVerificationStage) => {
    let nextStage: DataVerificationStage = 'dichiarato';
    if (currentStage === 'dichiarato') nextStage = 'verificato';
    else if (currentStage === 'verificato') nextStage = 'validato';
    else if (currentStage === 'validato') nextStage = 'pubblicato';
    else if (currentStage === 'pubblicato') nextStage = 'dichiarato';

    updateKPI(kpiId, { validationStatus: nextStage });
  };

  const filteredKpis = data.kpis.filter((k) => {
    const matchStage = selectedFilterStage === 'all' || k.validationStatus === selectedFilterStage;
    if (searchQuery.trim() !== '') {
      const q = searchQuery.toLowerCase();
      const matchSearch =
        k.code.toLowerCase().includes(q) ||
        k.name.toLowerCase().includes(q) ||
        k.domain.toLowerCase().includes(q) ||
        k.dataSource.toLowerCase().includes(q) ||
        k.responsibleOfficer.toLowerCase().includes(q);
      if (!matchSearch) return false;
    }
    return matchStage;
  });

  return (
    <div className="space-y-6">
      {/* Header Banner */}
      <div className="bg-white rounded-xl border border-stone-200 p-5 lg:p-6 shadow-xs">
        <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
          <div className="space-y-1">
            <div className="flex items-center gap-2">
              <span className="text-[10px] font-bold uppercase px-2 py-0.5 rounded bg-teal-50 text-teal-800 border border-teal-200">
                Modulo 5 • Intelligence Layer
              </span>
              <span className="text-xs text-stone-500 font-medium">Ciclo di Rilevazione e Validazione</span>
            </div>
            <h2 className="text-xl sm:text-2xl font-bold text-[#242424] tracking-tight flex items-center gap-2">
              <RefreshCw size={22} className="text-teal-700" />
              Flussi di Monitoraggio e Workflow di Validazione dei Dati
            </h2>
            <p className="text-xs sm:text-sm text-stone-600 max-w-4xl leading-relaxed">
              Tracciamento del ciclo di vita del dato di monitoraggio: dalla rilevazione operativa ad opera di ASTER e dei singoli uffici comunali, fino alla validazione direzionale e alla pubblicazione per gli organi di governo e per la cittadinanza.
            </p>
          </div>
        </div>

        {/* Workflow Diagram */}
        <div className="mt-6 pt-4 border-t border-stone-100">
          <h3 className="text-xs font-bold uppercase tracking-wider text-stone-500 mb-3">
            Modello Organizzativo del Flusso di Monitoraggio
          </h3>
          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-2.5">
            {workflowSteps.map((step, idx) => (
              <div
                key={idx}
                className="bg-stone-50 p-3 rounded-lg border border-stone-200/80 flex flex-col justify-between relative group hover:border-teal-400 transition-all"
              >
                <div>
                  <div className="w-5 h-5 rounded-full bg-teal-700 text-white font-bold text-[10px] flex items-center justify-center mb-1.5">
                    {step.number}
                  </div>
                  <div className="font-bold text-xs text-stone-900 leading-snug">{step.title}</div>
                  <div className="text-[10px] text-stone-500 mt-1 leading-tight">{step.desc}</div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* 4 DATA VERIFICATION STAGES PILL FILTER */}
      <div className="bg-white rounded-xl border border-stone-200 p-4 shadow-xs flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3">
        <div className="flex items-center gap-2 overflow-x-auto text-xs pb-1 sm:pb-0">
          <span className="font-bold text-stone-700 whitespace-nowrap">Stato del Dato:</span>
          <button
            onClick={() => setSelectedFilterStage('all')}
            className={`px-3 py-1.5 rounded-lg font-semibold whitespace-nowrap transition-colors ${
              selectedFilterStage === 'all'
                ? 'bg-stone-900 text-white'
                : 'bg-stone-100 text-stone-700 hover:bg-stone-200'
            }`}
          >
            Tutti gli Stati ({data.kpis.length})
          </button>
          <button
            onClick={() => setSelectedFilterStage('dichiarato')}
            className={`px-3 py-1.5 rounded-lg font-semibold whitespace-nowrap transition-colors ${
              selectedFilterStage === 'dichiarato'
                ? 'bg-amber-600 text-white'
                : 'bg-amber-50 text-amber-800 hover:bg-amber-100 border border-amber-200'
            }`}
          >
            1. Dato Dichiarato ({data.kpis.filter((k) => k.validationStatus === 'dichiarato').length})
          </button>
          <button
            onClick={() => setSelectedFilterStage('verificato')}
            className={`px-3 py-1.5 rounded-lg font-semibold whitespace-nowrap transition-colors ${
              selectedFilterStage === 'verificato'
                ? 'bg-blue-600 text-white'
                : 'bg-blue-50 text-blue-800 hover:bg-blue-100 border border-blue-200'
            }`}
          >
            2. Dato Verificato ({data.kpis.filter((k) => k.validationStatus === 'verificato').length})
          </button>
          <button
            onClick={() => setSelectedFilterStage('validato')}
            className={`px-3 py-1.5 rounded-lg font-semibold whitespace-nowrap transition-colors ${
              selectedFilterStage === 'validato'
                ? 'bg-emerald-600 text-white'
                : 'bg-emerald-50 text-emerald-800 hover:bg-emerald-100 border border-emerald-200'
            }`}
          >
            3. Dato Validato ({data.kpis.filter((k) => k.validationStatus === 'validato').length})
          </button>
          <button
            onClick={() => setSelectedFilterStage('pubblicato')}
            className={`px-3 py-1.5 rounded-lg font-semibold whitespace-nowrap transition-colors ${
              selectedFilterStage === 'pubblicato'
                ? 'bg-purple-600 text-white'
                : 'bg-purple-50 text-purple-800 hover:bg-purple-100 border border-purple-200'
            }`}
          >
            4. Dato Pubblicato ({data.kpis.filter((k) => k.validationStatus === 'pubblicato').length})
          </button>
        </div>
      </div>

      {/* KPI Workflows Stream Grid */}
      <div className="grid grid-cols-1 gap-4">
        {filteredKpis.map((kpi) => (
          <div
            key={kpi.id}
            className="bg-white rounded-xl border border-stone-200 p-5 shadow-xs space-y-3 hover:border-teal-300 transition-all"
          >
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2 pb-3 border-b border-stone-100">
              <div className="space-y-0.5">
                <div className="flex items-center gap-2">
                  <span className="font-bold text-xs px-2 py-0.5 rounded bg-stone-100 text-stone-800">
                    {kpi.code}
                  </span>
                  <span className="text-xs font-semibold text-stone-600">{kpi.domain}</span>
                </div>
                <h3 className="font-bold text-sm text-[#242424] mt-0.5">{kpi.name}</h3>
              </div>

              <div className="flex items-center gap-2 self-start sm:self-center">
                <DataStageBadge stage={kpi.validationStatus} size="md" />
                <button
                  onClick={() => handleStageAdvance(kpi.id, kpi.validationStatus)}
                  className="px-2.5 py-1 text-xs font-medium rounded-lg bg-stone-100 hover:bg-stone-200 text-stone-800 flex items-center gap-1 transition-colors"
                  title="Simula passaggio allo stato successivo"
                >
                  <ArrowRight size={13} />
                  <span>Avanza Stato</span>
                </button>
              </div>
            </div>

            {/* Workflow Attributes */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3 text-xs">
              <div className="p-3 bg-stone-50 rounded-lg border border-stone-200/60">
                <span className="text-stone-500 font-medium">Responsabile della Rilevazione:</span>
                <div className="font-bold text-stone-900 mt-0.5">{kpi.responsibleOfficer}</div>
              </div>

              <div className="p-3 bg-stone-50 rounded-lg border border-stone-200/60">
                <span className="text-stone-500 font-medium">Fonte Informativa:</span>
                <div className="font-semibold text-stone-800 mt-0.5 truncate">{kpi.dataSource}</div>
              </div>

              <div className="p-3 bg-stone-50 rounded-lg border border-stone-200/60">
                <span className="text-stone-500 font-medium">Frequenza di Aggiornamento:</span>
                <div className="font-semibold text-stone-800 mt-0.5">{kpi.updateFrequency}</div>
              </div>

              <div className="p-3 bg-stone-50 rounded-lg border border-stone-200/60">
                <span className="text-stone-500 font-medium">Ultima Rilevazione:</span>
                <div className="font-semibold text-stone-800 mt-0.5">
                  {kpi.lastSurveyDate ? formatDate(kpi.lastSurveyDate) : 'Da rilevare'}
                </div>
              </div>
            </div>

            {/* Evidences & History */}
            <div className="pt-2 text-xs space-y-2">
              <div className="flex items-start gap-2 text-stone-700">
                <FileCheck2 size={15} className="text-teal-700 shrink-0 mt-0.5" />
                <span>
                  <strong>Evidenza Documentale Allegata:</strong> {kpi.evidence}
                </span>
              </div>

              {kpi.history && kpi.history.length > 0 && (
                <div className="mt-3 p-3 bg-stone-50/70 rounded-lg border border-stone-200/50">
                  <span className="font-bold text-stone-800 flex items-center gap-1.5 mb-2">
                    <History size={14} className="text-stone-500" /> Storico Rilevazioni e Validazioni:
                  </span>
                  <div className="space-y-1.5">
                    {kpi.history.map((obs, oIdx) => (
                      <div
                        key={oIdx}
                        className="flex flex-col sm:flex-row sm:items-center justify-between text-[11px] py-1 border-b border-stone-200/40 last:border-0"
                      >
                        <div className="flex items-center gap-2">
                          <span className="font-bold text-stone-800">{obs.period}</span>
                          <span className="text-stone-500">({formatDate(obs.date)})</span>
                          <span className="text-stone-600">Rilevatore: {obs.recordedBy}</span>
                        </div>
                        <div className="flex items-center gap-2 mt-1 sm:mt-0">
                          <span className="font-semibold text-stone-900">
                            Valore: {obs.actualValue !== null ? obs.actualValue : 'Non rilevato'}
                          </span>
                          <DataStageBadge stage={obs.stage} size="sm" />
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

