import React, { useState } from 'react';
import {
  Compass,
  Plus,
  Filter,
  CheckCircle2,
  FileCheck2,
  AlertCircle,
  Users,
  Layers,
  Target,
  ArrowRight,
  ShieldCheck,
  Activity,
  Edit3
} from 'lucide-react';
import { useData } from '../../store/DataContext';
import { StrategyInitiative, DocumentFormalizationStatus } from '../../types';
import { FormalizationBadge } from '../../components/common/StatusBadge';
import { formatDate } from '../../utils';

export const StrategyBuilderView: React.FC = () => {
  const { data, updateStrategyInitiative, searchQuery } = useData();
  const [selectedCategory, setSelectedCategory] = useState<string>('all');
  const [filterStatus, setFilterStatus] = useState<string>('all');
  const [editingItem, setEditingItem] = useState<StrategyInitiative | null>(null);

  const categories = [
    'Assessment',
    'Iniziativa esistente',
    'Fabbisogno',
    'Criticità',
    'Obiettivo',
    'Priorità'
  ];

  const formalizationSteps: { status: DocumentFormalizationStatus; label: string; step: number }[] = [
    { status: 'bozza', label: 'Bozza', step: 1 },
    { status: 'in_condivisione', label: 'In Condivisione', step: 2 },
    { status: 'validato_tecnicamente', label: 'Validato Tecnicamente', step: 3 },
    { status: 'proposto_approvazione', label: 'Proposto Approvazione', step: 4 },
    { status: 'approvato', label: 'Approvato', step: 5 },
    { status: 'in_attuazione', label: 'In Attuazione', step: 6 },
    { status: 'in_monitoraggio', label: 'In Monitoraggio', step: 7 }
  ];

  const filteredInitiatives = data.strategyInitiatives.filter((item) => {
    if (searchQuery.trim() !== '') {
      const q = searchQuery.toLowerCase();
      const match =
        item.title.toLowerCase().includes(q) ||
        item.description.toLowerCase().includes(q) ||
        item.category.toLowerCase().includes(q) ||
        item.responsibleOfficer.toLowerCase().includes(q);
      if (!match) return false;
    }
    const matchCategory = selectedCategory === 'all' || item.category === selectedCategory;
    const matchStatus = filterStatus === 'all' || item.formalizationStatus === filterStatus;
    return matchCategory && matchStatus;
  });

  const handleStatusChange = (id: string, newStatus: DocumentFormalizationStatus) => {
    updateStrategyInitiative(id, { formalizationStatus: newStatus });
  };

  return (
    <div className="space-y-6">
      {/* Header & Strategic Mission */}
      <div className="bg-white rounded-xl border border-stone-200 p-5 lg:p-6 shadow-xs">
        <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
          <div className="space-y-1">
            <div className="flex items-center gap-2">
              <span className="text-[10px] font-bold uppercase px-2 py-0.5 rounded bg-[#B3101C]/10 text-[#B3101C]">
                Modulo 1 • Strategy Layer
              </span>
              <span className="text-xs text-stone-500 font-medium">Comune di Mantova</span>
            </div>
            <h2 className="text-xl sm:text-2xl font-bold text-[#242424] tracking-tight flex items-center gap-2">
              <Compass size={22} className="text-[#B3101C]" />
              Strategy Builder — Costruzione della Strategia Digitale
            </h2>
            <p className="text-xs sm:text-sm text-stone-600 max-w-4xl leading-relaxed">
              Ambiente dedicato alla formulazione, ricognizione e progressiva formalizzazione della strategia unitaria del Comune di Mantova. Consente di censire bisogni, priorità, criticità e collegarli agli strumenti programmatori (Linee di Mandato, DUP 2027–2029 e Piano Triennale ICT).
            </p>
          </div>
        </div>

        {/* Notice on Administrative Verification */}
        <div className="mt-4 p-3 bg-amber-50 border border-amber-200 rounded-lg text-xs text-amber-900 flex items-start gap-2.5">
          <AlertCircle size={16} className="text-amber-700 shrink-0 mt-0.5" />
          <div>
            <strong className="font-semibold">Regola Metodologica:</strong> Gli stati documentali rappresentano il modello di avanzamento della proposta strategica. La modifica dello stato documentale nella piattaforma non sostituisce né simula l'effettiva deliberazione amministrativa, di esclusiva competenza degli organi dell’Ente (Giunta / Consiglio Comunale).
          </div>
        </div>
      </div>

      {/* FORMALIZATION LIFECYCLE PROGRESS PIPELINE */}
      <div className="bg-white rounded-xl border border-stone-200 p-5 shadow-xs">
        <h3 className="text-xs font-bold uppercase tracking-wider text-stone-500 mb-3">
          Ciclo di Formalizzazione Istituzionale degli Elementi Strategici
        </h3>
        <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-7 gap-2 text-center text-xs">
          {formalizationSteps.map((step) => {
            const count = data.strategyInitiatives.filter((i) => i.formalizationStatus === step.status).length;
            return (
              <div
                key={step.status}
                onClick={() => setFilterStatus(filterStatus === step.status ? 'all' : step.status)}
                className={`p-2.5 rounded-lg border cursor-pointer transition-all ${
                  filterStatus === step.status
                    ? 'border-[#B3101C] bg-[#F9EFF0] text-[#B3101C] font-bold shadow-xs'
                    : 'border-stone-200 bg-stone-50 hover:bg-stone-100 text-stone-700'
                }`}
              >
                <div className="text-[10px] text-stone-400 font-semibold mb-1">Passo {step.step}</div>
                <div className="font-bold text-xs truncate">{step.label}</div>
                <div className="text-base font-bold mt-1 text-[#242424]">{count}</div>
              </div>
            );
          })}
        </div>
      </div>

      {/* Filters & Actions Bar */}
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 bg-white p-3.5 rounded-xl border border-stone-200 shadow-xs">
        {/* Category Tabs */}
        <div className="flex items-center gap-1.5 overflow-x-auto pb-1 sm:pb-0 text-xs">
          <button
            onClick={() => setSelectedCategory('all')}
            className={`px-3 py-1.5 rounded-lg font-medium whitespace-nowrap transition-colors ${
              selectedCategory === 'all'
                ? 'bg-[#B3101C] text-white'
                : 'bg-stone-100 text-stone-700 hover:bg-stone-200'
            }`}
          >
            Tutte le Aree ({data.strategyInitiatives.length})
          </button>
          {categories.map((cat) => {
            const catCount = data.strategyInitiatives.filter((i) => i.category === cat).length;
            return (
              <button
                key={cat}
                onClick={() => setSelectedCategory(cat)}
                className={`px-3 py-1.5 rounded-lg font-medium whitespace-nowrap transition-colors ${
                  selectedCategory === cat
                    ? 'bg-[#B3101C] text-white'
                    : 'bg-stone-100 text-stone-700 hover:bg-stone-200'
                }`}
              >
                {cat} ({catCount})
              </button>
            );
          })}
        </div>

        {filterStatus !== 'all' && (
          <button
            onClick={() => setFilterStatus('all')}
            className="text-xs text-[#B3101C] hover:underline font-semibold self-end sm:self-center"
          >
            Azzera filtro stato ({filterStatus})
          </button>
        )}
      </div>

      {/* Initiatives Cards Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {filteredInitiatives.map((item) => {
          const axis = data.strategicAxes.find((a) => a.id === item.strategicAxisId);
          return (
            <div
              key={item.id}
              className="bg-white rounded-xl border border-stone-200 p-5 shadow-xs hover:border-stone-300 transition-all flex flex-col justify-between"
            >
              <div>
                {/* Category & Status */}
                <div className="flex items-start justify-between gap-2 pb-2 border-b border-stone-100">
                  <span className="text-[11px] font-bold uppercase tracking-wider px-2 py-0.5 rounded bg-stone-100 text-stone-700">
                    {item.category}
                  </span>
                  <FormalizationBadge status={item.formalizationStatus} size="sm" />
                </div>

                {/* Title & Description */}
                <h3 className="font-bold text-sm text-[#242424] mt-2.5 leading-snug">
                  {item.title}
                </h3>
                <p className="text-xs text-stone-600 mt-2 leading-relaxed">
                  {item.description}
                </p>

                {/* Metadata details */}
                <div className="mt-4 pt-3 border-t border-stone-100 space-y-2 text-xs">
                  <div className="flex items-center gap-1.5 text-stone-700">
                    <Layers size={13} className="text-stone-400 shrink-0" />
                    <span className="text-stone-500">Asse:</span>
                    <strong className="text-stone-900 truncate">
                      {axis ? `${axis.title}` : item.strategicAxisId}
                    </strong>
                  </div>

                  <div className="flex items-center gap-1.5 text-stone-700">
                    <Target size={13} className="text-stone-400 shrink-0" />
                    <span className="text-stone-500">Strumento:</span>
                    <span className="font-medium text-stone-900 truncate">{item.programmingToolLink}</span>
                  </div>

                  <div className="flex items-start gap-1.5 text-stone-700">
                    <Users size={13} className="text-stone-400 shrink-0 mt-0.5" />
                    <span className="text-stone-500">Soggetti:</span>
                    <span className="text-stone-800 text-[11px]">{item.involvedEntities.join(', ')}</span>
                  </div>

                  {item.validationNotes && (
                    <div className="mt-2 p-2 bg-stone-50 rounded border border-stone-200/70 text-[11px] text-stone-600">
                      <span className="font-semibold text-stone-700">Stato avanzamento:</span> {item.validationNotes}
                    </div>
                  )}
                </div>
              </div>

              {/* Status Selector dropdown & update action */}
              <div className="mt-4 pt-3 border-t border-stone-100 flex items-center justify-between gap-2">
                <span className="text-[11px] text-stone-500">Aggiorna stato:</span>
                <select
                  value={item.formalizationStatus}
                  onChange={(e) => handleStatusChange(item.id, e.target.value as DocumentFormalizationStatus)}
                  className="text-xs bg-stone-50 border border-stone-200 rounded px-2 py-1 font-medium text-stone-800 focus:outline-none focus:ring-1 focus:ring-[#B3101C] cursor-pointer"
                >
                  <option value="bozza">Bozza</option>
                  <option value="in_condivisione">In Condivisione</option>
                  <option value="validato_tecnicamente">Validato Tecnicamente</option>
                  <option value="proposto_approvazione">Proposto per Approvazione</option>
                  <option value="approvato">Approvato</option>
                  <option value="in_attuazione">In Attuazione</option>
                  <option value="in_monitoraggio">In Monitoraggio</option>
                </select>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

