import React from 'react';
import { HashRouter, Routes, Route, Navigate } from 'react-router-dom';
import { DataProvider } from './store/DataContext';
import { AuthProvider } from './store/AuthContext';
import { AppLayout } from './components/layout/AppLayout';
import { ProtectedRoute } from './components/auth/ProtectedRoute';
import { LoginView } from './features/auth/LoginView';

// Features
import { ExecutiveOverview } from './features/overview/ExecutiveOverview';
import { StrategyBuilderView } from './features/strategy/StrategyBuilderView';
import { AsterPortfolioView } from './features/aster/AsterPortfolioView';
import { ControlRoomView } from './features/control-room/ControlRoomView';
import { GovernanceRaciView } from './features/governance/GovernanceRaciView';
import { MonitoringWorkflowView } from './features/monitoring/MonitoringWorkflowView';
import { MaturityAssessmentView } from './features/maturity/MaturityAssessmentView';
import { MandateGoalsView } from './features/objectives/MandateGoalsView';
import { StrategicAxesView } from './features/strategy/StrategicAxesView';
import { ProjectsPortfolioView } from './features/projects/ProjectsPortfolioView';
import { KPIPerformanceView } from './features/kpi/KPIPerformanceView';
import { RoadmapGanttView } from './features/roadmap/RoadmapGanttView';
import { UrbanIntelligenceView } from './features/urban/UrbanIntelligenceView';
import { DataGovernanceView } from './features/data-governance/DataGovernanceView';
import { InteroperabilityView } from './features/interoperability/InteroperabilityView';
import { AIGovernanceView } from './features/ai-governance/AIGovernanceView';
import { ReportingView } from './features/reporting/ReportingView';
import { DataManagementView } from './features/administration/DataManagementView';
import { SourcesRegistryView } from './features/sources/SourcesRegistryView';
import { ExecutivePresentationView } from './features/presentation/ExecutivePresentationView';

export const App: React.FC = () => {
  return (
    <AuthProvider>
      <DataProvider>
        <HashRouter>
          <Routes>
            {/* Dedicated Institutional Login with MFA */}
            <Route path="/login" element={<LoginView />} />

            {/* Executive Presentation full screen mode outside standard chrome (Protected) */}
            <Route
              path="/presentation"
              element={
                <ProtectedRoute>
                  <ExecutivePresentationView />
                </ProtectedRoute>
              }
            />

            {/* Standard Shell (Protected by AppLayout & ProtectedRoute) */}
            <Route
              path="/"
              element={
                <ProtectedRoute>
                  <AppLayout />
                </ProtectedRoute>
              }
            >
              <Route index element={<ExecutiveOverview />} />
              <Route path="strategy-builder" element={<StrategyBuilderView />} />
              <Route path="aster-portfolio" element={<AsterPortfolioView />} />
              <Route path="control-room" element={<ControlRoomView />} />
              <Route path="governance-raci" element={<GovernanceRaciView />} />
              <Route path="monitoring-workflows" element={<MonitoringWorkflowView />} />
              <Route path="maturity-assessment" element={<MaturityAssessmentView />} />
              <Route path="mandate-goals" element={<MandateGoalsView />} />
              <Route path="strategic-axes" element={<StrategicAxesView />} />
              <Route path="projects" element={<ProjectsPortfolioView />} />
              <Route path="kpi-performance" element={<KPIPerformanceView />} />
              <Route path="roadmap" element={<RoadmapGanttView />} />
              <Route path="urban-intelligence" element={<UrbanIntelligenceView />} />
              <Route path="data-governance" element={<DataGovernanceView />} />
              <Route path="interoperability" element={<InteroperabilityView />} />
              <Route path="ai-governance" element={<AIGovernanceView />} />
              <Route path="reporting" element={<ReportingView />} />
              <Route path="data-management" element={<DataManagementView />} />
              <Route path="sources" element={<SourcesRegistryView />} />
              <Route path="*" element={<Navigate to="/" replace />} />
            </Route>
          </Routes>
        </HashRouter>
      </DataProvider>
    </AuthProvider>
  );
};

export default App;
