import React, { useState } from 'react';
import {
  Layers,
  Database,
  Network,
  Cpu,
  MapPin,
  Workflow,
  GraduationCap,
  Target,
  FolderKanban,
  CheckCircle2,
  ArrowRight,
  TrendingUp,
  FileText
} from 'lucide-react';
import { useData } from '../../store/DataContext';
import { StrategicAxis } from '../../types';
import { StatusBadge } from '../../components/common/StatusBadge';
import { formatPercent } from '../../utils';

export const StrategicAxesView: React.FC = () => {
  const { data } = useData();
  const [selectedAxisId, setSelectedAxisId] = useState<string>(data.strategicAxes[0].id);

  const currentAxis = data.strategicAxes.find((a) => a.id === selectedAxisId) || data.strategicAxes[0];

  const axisProjects = data.projects.filter(
    (p) => p.primaryAxis === currentAxis.id || p.secondaryAxes.includes(currentAxis.id)
  );

  const axisObjectives = data.managementObjectives.filter((obj) =>
    obj.relatedAxes.includes(currentAxis.id)
  );

  const axisKPIs = data.kpis.filter((k) =>
    axisProjects.some((p) => p.relatedKPIs.includes(k.id)) ||
    axisObjectives.some((o) => o.relatedKPIs.includes(k.id))
  );

  const getAxisIcon = (iconName: string) => {
    switch (iconName) {
      case 'Database': return <Database size={20} />;
      case 'Network': return <Network size={20} />;
      case 'Cpu': return <Cpu size={20} />;
      case 'MapPin': return <MapPin size={20} />;
      case 'Workflow': return <Workflow size={20} />;
      case 'GraduationCap': return <GraduationCap size={20} />;
      default: return <Layers size={20} />;
    }
  };

  return (
    <div className="space-y-6">
      {/* Header Banner */}
      <div className="bg-white rounded-xl border border-stone-200 p-5 lg:p-6 shadow-xs">
        <div className="space-y-1">
          <div className="flex items-center gap-2">
            <span className="text-[10px] font-bold uppercase px-2 py-0.5 rounded bg-stone-100 text-stone-700">
              Piano Strategico Digitale 2027–2029
            </span>
            <span className="text-xs text-stone-500 font-medium">Architettura Strategica Unitaria</span>
          </div>
          <h2 className="text-xl sm:text-2xl font-bold text-[#242424] tracking-tight flex items-center gap-2">
            <Layers size={22} className="text-[#B3101C]" />
            I Sei Assi Strategici della Trasformazione Digitale di Mantova
          </h2>
          <p className="text-xs sm:text-sm text-stone-600 max-w-4xl leading-relaxed">
            Il dato costituisce la base comune; l’interoperabilità abilita lo scambio; l’IoT raccoglie informazioni dal territorio e dagli asset urbani; l’intelligenza artificiale aggiunge capacità di analisi e supporto; la governance garantisce responsabilità, sicurezza e sostenibilità.
          </p>
        </div>

        {/* 6 Axes Selector Navigation Bar */}
        <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-6 gap-2 mt-5 pt-4 border-t border-stone-100">
          {data.strategicAxes.map((axis) => {
            const isSelected = axis.id === selectedAxisId;
            return (
              <button
                key={axis.id}
                onClick={() => setSelectedAxisId(axis.id)}
                className={`p-3 rounded-xl border text-left transition-all flex flex-col justify-between ${
                  isSelected
                    ? 'border-[#B3101C] bg-[#F9EFF0]/80 shadow-xs ring-1 ring-[#B3101C]'
                    : 'border-stone-200 bg-stone-50 hover:bg-stone-100 text-stone-700'
                }`}
              >
                <div>
                  <div className="flex items-center justify-between mb-1.5">
                    <span className={`text-[10px] font-bold px-1.5 py-0.5 rounded ${
                      isSelected ? 'bg-[#B3101C] text-white' : 'bg-stone-200 text-stone-800'
                    }`}>
                      ASSE {axis.number}
                    </span>
                    <span style={{ color: axis.color }}>{getAxisIcon(axis.iconName)}</span>
                  </div>
                  <div className="font-bold text-xs text-stone-900 leading-snug line-clamp-2">
                    {axis.title}
                  </div>
                </div>
              </button>
            );
          })}
        </div>
      </div>

      {/* SELECTED AXIS DEEP-DIVE CARD */}
      <div className="bg-white rounded-xl border border-stone-200 p-6 shadow-xs space-y-6">
        {/* Axis Header */}
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 pb-4 border-b border-stone-100">
          <div className="flex items-center gap-3">
            <div
              className="w-12 h-12 rounded-xl flex items-center justify-center text-white shrink-0 shadow-xs"
              style={{ backgroundColor: currentAxis.color }}
            >
              {getAxisIcon(currentAxis.iconName)}
            </div>
            <div>
              <span className="text-[11px] font-bold uppercase tracking-wider text-stone-500">
                ASSE STRATEGICO {currentAxis.number}
              </span>
              <h3 className="text-xl font-bold text-[#242424]">{currentAxis.title}</h3>
              <p className="text-xs text-stone-600 mt-0.5 font-medium">{currentAxis.description}</p>
            </div>
          </div>

          <div className="p-3 bg-stone-50 rounded-lg border border-stone-200/70 text-xs self-start md:self-center">
            <span className="text-stone-500 font-medium">Coordinamento Lead:</span>
            <div className="font-bold text-stone-900 mt-0.5">{currentAxis.leadRole}</div>
          </div>
        </div>

        {/* Expected Outcome Box */}
        <div className="p-4 rounded-xl bg-stone-900 text-white flex items-start gap-3 shadow-xs">
          <Target size={20} className="text-[#ED1C24] shrink-0 mt-0.5" />
          <div>
            <span className="text-[10px] font-bold uppercase tracking-wider text-[#ED1C24]">
              Esito Atteso al 2029 (Piano rev1)
            </span>
            <div className="text-sm font-semibold text-white mt-1 leading-relaxed">
              "{currentAxis.expectedOutcome}"
            </div>
          </div>
        </div>

        {/* Two Columns: Domains and Priority Actions */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-5 text-xs">
          {/* Domains */}
          <div className="p-4 rounded-xl bg-stone-50 border border-stone-200/80 space-y-2">
            <h4 className="font-bold text-sm text-stone-900 flex items-center gap-1.5">
              <Layers size={16} className="text-stone-600" />
              Ambiti Tematici Presidiati
            </h4>
            <ul className="space-y-1.5 mt-2">
              {currentAxis.domains.map((dom, dIdx) => (
                <li key={dIdx} className="flex items-start gap-2 text-stone-700">
                  <span className="w-1.5 h-1.5 rounded-full bg-stone-400 mt-1.5 shrink-0" />
                  <span className="leading-snug">{dom}</span>
                </li>
              ))}
            </ul>
          </div>

          {/* Priority Actions */}
          <div className="p-4 rounded-xl bg-stone-50 border border-stone-200/80 space-y-2">
            <h4 className="font-bold text-sm text-stone-900 flex items-center gap-1.5">
              <CheckCircle2 size={16} className="text-emerald-700" />
              Azioni Prioritarie di Mandato
            </h4>
            <ul className="space-y-1.5 mt-2">
              {currentAxis.priorityActions.map((act, aIdx) => (
                <li key={aIdx} className="flex items-start gap-2 text-stone-700">
                  <span className="w-4 h-4 rounded bg-emerald-100 text-emerald-800 text-[10px] font-bold flex items-center justify-center shrink-0 mt-0.5">
                    {aIdx + 1}
                  </span>
                  <span className="leading-snug font-medium">{act}</span>
                </li>
              ))}
            </ul>
          </div>
        </div>

        {/* Connected Projects and KPIs Strip */}
        <div className="pt-4 border-t border-stone-100 grid grid-cols-1 md:grid-cols-2 gap-5">
          {/* Projects */}
          <div className="space-y-2">
            <h4 className="font-bold text-xs uppercase tracking-wider text-stone-500 flex items-center gap-1.5">
              <FolderKanban size={14} className="text-blue-700" />
              Progetti Prioritari Collegati ({axisProjects.length})
            </h4>
            <div className="space-y-1.5">
              {axisProjects.map((prj) => (
                <div
                  key={prj.id}
                  className="p-2.5 rounded-lg border border-stone-200/70 bg-white hover:bg-stone-50 transition-colors flex items-center justify-between text-xs"
                >
                  <div className="space-y-0.5">
                    <span className="font-bold text-stone-900">{prj.code} • {prj.title}</span>
                    <div className="text-[11px] text-stone-500">{prj.involvedSectors.slice(0, 2).join(', ')}</div>
                  </div>
                  <span className="font-bold text-stone-800">{formatPercent(prj.physicalProgress)}</span>
                </div>
              ))}
            </div>
          </div>

          {/* KPIs */}
          <div className="space-y-2">
            <h4 className="font-bold text-xs uppercase tracking-wider text-stone-500 flex items-center gap-1.5">
              <Target size={14} className="text-emerald-700" />
              Indicatori di Performance Connessi ({axisKPIs.length})
            </h4>
            <div className="space-y-1.5">
              {axisKPIs.map((kpi) => (
                <div
                  key={kpi.id}
                  className="p-2.5 rounded-lg border border-stone-200/70 bg-white hover:bg-stone-50 transition-colors flex items-center justify-between text-xs"
                >
                  <div className="space-y-0.5">
                    <span className="font-bold text-stone-900">{kpi.code} • {kpi.domain}</span>
                    <div className="text-[11px] text-stone-500 line-clamp-1">{kpi.name}</div>
                  </div>
                  <StatusBadge status={kpi.achievementStatus} size="sm" />
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

