import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';
import * as XLSX from 'xlsx';
import Papa from 'papaparse';
import { OperationalStatus, DocumentFormalizationStatus, DataVerificationStage } from '../types';

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export function formatPercent(value: number | null | undefined): string {
  if (value === null || value === undefined) return 'Non rilevato';
  return `${value.toFixed(1).replace('.0', '')}%`;
}

export function formatCurrency(amount: number | null | undefined): string {
  if (amount === null || amount === undefined) return 'Non definito';
  return new Intl.NumberFormat('it-IT', { style: 'currency', currency: 'EUR', maximumFractionDigits: 0 }).format(amount);
}

export function formatDate(dateString: string | null | undefined): string {
  if (!dateString) return 'Da pianificare';
  try {
    const parts = dateString.split('-');
    if (parts.length === 3) {
      return `${parts[2]}/${parts[1]}/${parts[0]}`;
    }
    return dateString;
  } catch {
    return dateString;
  }
}

export function getOperationalStatusLabel(status: OperationalStatus): string {
  switch (status) {
    case 'in_linea':
      return 'In linea';
    case 'da_attenzionare':
      return 'Da attenzionare';
    case 'critico':
      return 'Critico';
    case 'completato':
      return 'Completato';
    case 'non_avviato':
      return 'Non avviato';
    case 'non_rilevato':
      return 'Non rilevato';
    default:
      return status;
  }
}

