import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import {
  StrategicGoal,
  ManagementObjective,
  StrategicAxis,
  Project,
  AsterIntervention,
  KPI,
  KPIObservation,
  StrategyInitiative,
  DigitalMaturityDimension,
  RACIMatrixEntry,
  DecisionLogEntry,
  CriticalityLogEntry,
  DatasetEntity,
  APIIntegration,
  AIUseCase,
  IoTAsset,
  GeoLayerDefinition,
  SourceDocumentRecord,
  ArchitectureLayer
} from '../types';
import * as seed from '../data/seed';

const STORAGE_KEY = 'mantova_digitale_data_v1.1';
const STORAGE_MODIFIED_KEY = 'mantova_digitale_is_modified_v1.1';

export interface AppDataState {
  strategicGoal: StrategicGoal;
  managementObjectives: ManagementObjective[];
  strategicAxes: StrategicAxis[];
  projects: Project[];
  asterInterventions: AsterIntervention[];
  kpis: KPI[];
  strategyInitiatives: StrategyInitiative[];
  digitalMaturity: DigitalMaturityDimension[];
  raciMatrix: RACIMatrixEntry[];
  decisionLog: DecisionLogEntry[];
  criticalityLog: CriticalityLogEntry[];
  datasets: DatasetEntity[];
  apiIntegrations: APIIntegration[];
  aiUseCases: AIUseCase[];
  iotAssets: IoTAsset[];
  geoLayers: GeoLayerDefinition[];
  sourceDocuments: SourceDocumentRecord[];
}

export interface DataContextType {
  data: AppDataState;
  isLocalModified: boolean;
  selectedYear: string; // 'all' | '2027' | '2028' | '2029'
  setSelectedYear: (year: string) => void;
  selectedAxis: string; // 'all' or axis ID
  setSelectedAxis: (axis: string) => void;
  selectedLayer: ArchitectureLayer | 'all';
  setSelectedLayer: (layer: ArchitectureLayer | 'all') => void;
  searchQuery: string;
  setSearchQuery: (q: string) => void;

  // Updaters
  updateProject: (id: string, updates: Partial<Project>) => void;
  updateAsterIntervention: (id: string, updates: Partial<AsterIntervention>) => void;
  updateKPI: (id: string, updates: Partial<KPI>) => void;
  addKPIObservation: (kpiId: string, obs: KPIObservation) => void;
  updateStrategyInitiative: (id: string, updates: Partial<StrategyInitiative>) => void;
  updateMaturityDimension: (id: string, updates: Partial<DigitalMaturityDimension>) => void;
  addDecision: (decision: DecisionLogEntry) => void;
  updateDecision: (id: string, updates: Partial<DecisionLogEntry>) => void;
  addCriticality: (item: CriticalityLogEntry) => void;
  updateCriticality: (id: string, updates: Partial<CriticalityLogEntry>) => void;
  updateRACIEntry: (id: string, updates: Partial<RACIMatrixEntry>) => void;
  updateDataset: (id: string, updates: Partial<DatasetEntity>) => void;
  updateAPIIntegration: (id: string, updates: Partial<APIIntegration>) => void;
  updateAIUseCase: (id: string, updates: Partial<AIUseCase>) => void;
  updateIoTAsset: (id: string, updates: Partial<IoTAsset>) => void;

  // Persistence & Reset
  resetToOfficialSeed: () => void;
  exportJSON: () => string;
  importJSON: (jsonStr: string) => { success: boolean; error?: string };
}

const getInitialData = (): AppDataState => ({
  strategicGoal: seed.initialStrategicGoal00A,
  managementObjectives: seed.initialManagementObjectives,
  strategicAxes: seed.initialStrategicAxes,
  projects: seed.initialProjects,
  asterInterventions: seed.initialAsterInterventions,
  kpis: seed.initialKPIs,
  strategyInitiatives: seed.initialStrategyInitiatives,
  digitalMaturity: seed.initialDigitalMaturityDimensions,
  raciMatrix: seed.initialRACIMatrix,
  decisionLog: seed.initialDecisionLog,
  criticalityLog: seed.initialCriticalityLog,
  datasets: seed.initialDatasets,
  apiIntegrations: seed.initialAPIIntegrations,
  aiUseCases: seed.initialAIUseCases,
  iotAssets: seed.initialIoTAssets,
  geoLayers: seed.initialGeoLayers,
  sourceDocuments: seed.initialSourceDocuments
});

const DataContext = createContext<DataContextType | undefined>(undefined);

export const DataProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [data, setData] = useState<AppDataState>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      if (saved) {
        return JSON.parse(saved);
      }
    } catch (e) {
      console.warn('Errore lettura dati da localStorage, caricamento dati iniziali:', e);
    }
    return getInitialData();
  });

  const [isLocalModified, setIsLocalModified] = useState<boolean>(() => {
    return localStorage.getItem(STORAGE_MODIFIED_KEY) === 'true';
  });

  // Global filters
  const [selectedYear, setSelectedYear] = useState<string>('all');
  const [selectedAxis, setSelectedAxis] = useState<string>('all');
  const [selectedLayer, setSelectedLayer] = useState<ArchitectureLayer | 'all'>('all');
  const [searchQuery, setSearchQuery] = useState<string>('');

  // Save to localStorage whenever data changes
  const persist = (newData: AppDataState) => {
    setData(newData);
    setIsLocalModified(true);
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(newData));
      localStorage.setItem(STORAGE_MODIFIED_KEY, 'true');
    } catch (e) {
      console.error('Impossibile salvare in localStorage:', e);
    }
  };

  const updateProject = (id: string, updates: Partial<Project>) => {
    const updated = data.projects.map((p) => (p.id === id ? { ...p, ...updates, updatedAt: new Date().toISOString().split('T')[0] } : p));
    persist({ ...data, projects: updated });
  };

  const updateAsterIntervention = (id: string, updates: Partial<AsterIntervention>) => {
    const updated = data.asterInterventions.map((item) =>
      item.id === id ? { ...item, ...updates, updatedAt: new Date().toISOString().split('T')[0] } : item
    );
    persist({ ...data, asterInterventions: updated });
  };

  const updateKPI = (id: string, updates: Partial<KPI>) => {
    const updated = data.kpis.map((kpi) => {
      if (kpi.id !== id) return kpi;
      const combined = { ...kpi, ...updates };
      // Recalculate achievement percentage if current value or target changed
      if (combined.currentValue !== null && combined.target > 0) {
        if (combined.kpiType === 'percentage') {
          combined.achievementPercentage = Math.min(100, Math.round((combined.currentValue / combined.target) * 1000) / 10);
        } else if (combined.kpiType === 'numeric' || combined.kpiType === 'milestone') {
          combined.achievementPercentage = Math.min(100, Math.round((combined.currentValue / combined.target) * 1000) / 10);
        }
      }
      return combined;
    });
    persist({ ...data, kpis: updated });
  };

  const addKPIObservation = (kpiId: string, obs: KPIObservation) => {
    const updated = data.kpis.map((kpi) => {
      if (kpi.id !== kpiId) return kpi;
      const history = [...kpi.history, obs];
      return {
        ...kpi,
        history,
        currentValue: obs.actualValue,
        lastSurveyDate: obs.date,
        validationStatus: obs.stage,
        achievementPercentage:
          obs.actualValue !== null && kpi.target > 0
            ? Math.min(100, Math.round((obs.actualValue / kpi.target) * 1000) / 10)
            : kpi.achievementPercentage
      };
    });
    persist({ ...data, kpis: updated });
  };

  const updateStrategyInitiative = (id: string, updates: Partial<StrategyInitiative>) => {
    const updated = data.strategyInitiatives.map((item) =>
      item.id === id ? { ...item, ...updates, lastUpdated: new Date().toISOString().split('T')[0] } : item
    );
    persist({ ...data, strategyInitiatives: updated });
  };

  const updateMaturityDimension = (id: string, updates: Partial<DigitalMaturityDimension>) => {
    const updated = data.digitalMaturity.map((item) =>
      item.id === id ? { ...item, ...updates, assessmentDate: new Date().toISOString().split('T')[0] } : item
    );
    persist({ ...data, digitalMaturity: updated });
  };

  const addDecision = (decision: DecisionLogEntry) => {
    persist({ ...data, decisionLog: [decision, ...data.decisionLog] });
  };

  const updateDecision = (id: string, updates: Partial<DecisionLogEntry>) => {
    const updated = data.decisionLog.map((d) => (d.id === id ? { ...d, ...updates } : d));
    persist({ ...data, decisionLog: updated });
  };

  const addCriticality = (item: CriticalityLogEntry) => {
    persist({ ...data, criticalityLog: [item, ...data.criticalityLog] });
  };

  const updateCriticality = (id: string, updates: Partial<CriticalityLogEntry>) => {
    const updated = data.criticalityLog.map((c) => (c.id === id ? { ...c, ...updates, updatedAt: new Date().toISOString().split('T')[0] } : c));
    persist({ ...data, criticalityLog: updated });
  };

  const updateRACIEntry = (id: string, updates: Partial<RACIMatrixEntry>) => {
    const updated = data.raciMatrix.map((r) => (r.id === id ? { ...r, ...updates } : r));
    persist({ ...data, raciMatrix: updated });
  };

  const updateDataset = (id: string, updates: Partial<DatasetEntity>) => {
    const updated = data.datasets.map((d) => (d.id === id ? { ...d, ...updates } : d));
    persist({ ...data, datasets: updated });
  };

  const updateAPIIntegration = (id: string, updates: Partial<APIIntegration>) => {
    const updated = data.apiIntegrations.map((a) => (a.id === id ? { ...a, ...updates } : a));
    persist({ ...data, apiIntegrations: updated });
  };

  const updateAIUseCase = (id: string, updates: Partial<AIUseCase>) => {
    const updated = data.aiUseCases.map((u) => (u.id === id ? { ...u, ...updates } : u));
    persist({ ...data, aiUseCases: updated });
  };

  const updateIoTAsset = (id: string, updates: Partial<IoTAsset>) => {
    const updated = data.iotAssets.map((asset) => (asset.id === id ? { ...asset, ...updates } : asset));
    persist({ ...data, iotAssets: updated });
  };

  const resetToOfficialSeed = () => {
    const fresh = getInitialData();
    setData(fresh);
    setIsLocalModified(false);
    try {
      localStorage.removeItem(STORAGE_KEY);
      localStorage.removeItem(STORAGE_MODIFIED_KEY);
    } catch (e) {
      console.warn('Errore pulizia localStorage:', e);
    }
  };

  const exportJSON = () => {
    return JSON.stringify(data, null, 2);
  };

  const importJSON = (jsonStr: string) => {
    try {
      const parsed = JSON.parse(jsonStr);
      if (!parsed.projects || !parsed.kpis || !parsed.strategicAxes) {
        return { success: false, error: 'Formato file JSON non valido: mancano le strutture obbligatorie del Piano.' };
      }
      persist(parsed);
      return { success: true };
    } catch (err: any) {
      return { success: false, error: err.message || 'Errore durante la decodifica del file JSON' };
    }
  };

  return (
    <DataContext.Provider
      value={{
        data,
        isLocalModified,
        selectedYear,
        setSelectedYear,
        selectedAxis,
        setSelectedAxis,
        selectedLayer,
        setSelectedLayer,
        searchQuery,
        setSearchQuery,
        updateProject,
        updateAsterIntervention,
        updateKPI,
        addKPIObservation,
        updateStrategyInitiative,
        updateMaturityDimension,
        addDecision,
        updateDecision,
        addCriticality,
        updateCriticality,
        updateRACIEntry,
        updateDataset,
        updateAPIIntegration,
        updateAIUseCase,
        updateIoTAsset,
        resetToOfficialSeed,
        exportJSON,
        importJSON
      }}
    >
      {children}
    </DataContext.Provider>
  );
};

export const useData = (): DataContextType => {
  const context = useContext(DataContext);
  if (!context) {
    throw new Error('useData must be used within a DataProvider');
  }
  return context;
};
