import React from 'react';
import {
  CheckCircle2,
  AlertTriangle,
  AlertOctagon,
  CheckCheck,
  Clock,
  HelpCircle,
  FileEdit,
  Users,
  Check,
  FileCheck,
  ShieldCheck,
  Play,
  Activity,
  FileText,
  BadgeCheck,
  Globe
} from 'lucide-react';
import { OperationalStatus, DocumentFormalizationStatus, DataVerificationStage, ArchitectureLayer } from '../../types';
import { getOperationalStatusLabel, getFormalizationStatusLabel, getDataStageLabel } from '../../utils';

interface StatusBadgeProps {
  status: OperationalStatus;
  size?: 'sm' | 'md';
}

export const StatusBadge: React.FC<StatusBadgeProps> = ({ status, size = 'md' }) => {
  const iconSize = size === 'sm' ? 12 : 14;
  const padding = size === 'sm' ? 'px-2 py-0.5 text-xs' : 'px-2.5 py-1 text-xs font-medium';

  switch (status) {
    case 'in_linea':
      return (
        <span className={`inline-flex items-center gap-1.5 rounded-full bg-emerald-50 text-emerald-800 border border-emerald-200 ${padding}`}>
          <CheckCircle2 size={iconSize} className="text-emerald-600 shrink-0" aria-hidden="true" />
          <span>{getOperationalStatusLabel(status)}</span>
        </span>
      );
    case 'da_attenzionare':
      return (
        <span className={`inline-flex items-center gap-1.5 rounded-full bg-amber-50 text-amber-800 border border-amber-200 ${padding}`}>
          <AlertTriangle size={iconSize} className="text-amber-600 shrink-0" aria-hidden="true" />
          <span>{getOperationalStatusLabel(status)}</span>
        </span>
      );
    case 'critico':
      return (
        <span className={`inline-flex items-center gap-1.5 rounded-full bg-red-50 text-red-800 border border-red-200 ${padding}`}>
          <AlertOctagon size={iconSize} className="text-red-600 shrink-0" aria-hidden="true" />
          <span>{getOperationalStatusLabel(status)}</span>
        </span>
      );
    case 'completato':
      return (
        <span className={`inline-flex items-center gap-1.5 rounded-full bg-blue-50 text-blue-800 border border-blue-200 ${padding}`}>
          <CheckCheck size={iconSize} className="text-blue-600 shrink-0" aria-hidden="true" />
          <span>{getOperationalStatusLabel(status)}</span>
        </span>
      );
    case 'non_avviato':
      return (
        <span className={`inline-flex items-center gap-1.5 rounded-full bg-slate-100 text-slate-700 border border-slate-200 ${padding}`}>
          <Clock size={iconSize} className="text-slate-500 shrink-0" aria-hidden="true" />
          <span>{getOperationalStatusLabel(status)}</span>
        </span>
      );
    case 'non_rilevato':
    default:
      return (
        <span className={`inline-flex items-center gap-1.5 rounded-full bg-zinc-100 text-zinc-600 border border-zinc-200 ${padding}`}>
          <HelpCircle size={iconSize} className="text-zinc-400 shrink-0" aria-hidden="true" />
          <span>{getOperationalStatusLabel(status)}</span>
        </span>
      );
  }
};

interface FormalizationBadgeProps {
  status: DocumentFormalizationStatus;
  size?: 'sm' | 'md';
}

export const FormalizationBadge: React.FC<FormalizationBadgeProps> = ({ status, size = 'md' }) => {
  const iconSize = size === 'sm' ? 12 : 14;
  const padding = size === 'sm' ? 'px-2 py-0.5 text-xs' : 'px-2.5 py-1 text-xs font-medium';

  switch (status) {
    case 'bozza':
      return (
        <span className={`inline-flex items-center gap-1.5 rounded-md bg-stone-100 text-stone-700 border border-stone-200 ${padding}`}>
          <FileEdit size={iconSize} className="text-stone-500" />
          <span>{getFormalizationStatusLabel(status)}</span>
        </span>
      );
    case 'in_condivisione':
      return (
        <span className={`inline-flex items-center gap-1.5 rounded-md bg-sky-50 text-sky-800 border border-sky-200 ${padding}`}>
          <Users size={iconSize} className="text-sky-600" />
          <span>{getFormalizationStatusLabel(status)}</span>
        </span>
      );
    case 'validato_tecnicamente':
      return (
        <span className={`inline-flex items-center gap-1.5 rounded-md bg-indigo-50 text-indigo-800 border border-indigo-200 ${padding}`}>
          <Check size={iconSize} className="text-indigo-600" />
          <span>{getFormalizationStatusLabel(status)}</span>
        </span>
      );
    case 'proposto_approvazione':
      return (
        <span className={`inline-flex items-center gap-1.5 rounded-md bg-amber-50 text-amber-800 border border-amber-300 font-semibold ${padding}`}>
          <FileCheck size={iconSize} className="text-amber-600" />
          <span>{getFormalizationStatusLabel(status)}</span>
        </span>
      );
    case 'approvato':
      return (
        <span className={`inline-flex items-center gap-1.5 rounded-md bg-emerald-50 text-emerald-800 border border-emerald-300 font-semibold ${padding}`}>
          <ShieldCheck size={iconSize} className="text-emerald-600" />
          <span>{getFormalizationStatusLabel(status)}</span>
        </span>
      );
    case 'in_attuazione':
      return (
        <span className={`inline-flex items-center gap-1.5 rounded-md bg-purple-50 text-purple-800 border border-purple-200 ${padding}`}>
          <Play size={iconSize} className="text-purple-600" />
          <span>{getFormalizationStatusLabel(status)}</span>
        </span>
      );
    case 'in_monitoraggio':
      return (
        <span className={`inline-flex items-center gap-1.5 rounded-md bg-teal-50 text-teal-800 border border-teal-200 ${padding}`}>
          <Activity size={iconSize} className="text-teal-600" />
          <span>{getFormalizationStatusLabel(status)}</span>
        </span>
      );
    default:
      return <span>{status}</span>;
  }
};

interface DataStageBadgeProps {
  stage: DataVerificationStage;
  size?: 'sm' | 'md';
}

export const DataStageBadge: React.FC<DataStageBadgeProps> = ({ stage, size = 'md' }) => {
  const iconSize = size === 'sm' ? 12 : 14;
  const padding = size === 'sm' ? 'px-2 py-0.5 text-xs' : 'px-2.5 py-0.5 text-xs font-medium';

  switch (stage) {
    case 'dichiarato':
      return (
        <span className={`inline-flex items-center gap-1.5 rounded bg-amber-50 text-amber-800 border border-amber-200 ${padding}`}>
          <FileText size={iconSize} className="text-amber-600" />
          <span>{getDataStageLabel(stage)}</span>
        </span>
      );
    case 'verificato':
      return (
        <span className={`inline-flex items-center gap-1.5 rounded bg-blue-50 text-blue-800 border border-blue-200 ${padding}`}>
          <CheckCircle2 size={iconSize} className="text-blue-600" />
          <span>{getDataStageLabel(stage)}</span>
        </span>
      );
    case 'validato':
      return (
        <span className={`inline-flex items-center gap-1.5 rounded bg-emerald-50 text-emerald-800 border border-emerald-200 ${padding}`}>
          <BadgeCheck size={iconSize} className="text-emerald-600" />
          <span>{getDataStageLabel(stage)}</span>
        </span>
      );
    case 'pubblicato':
      return (
        <span className={`inline-flex items-center gap-1.5 rounded bg-purple-50 text-purple-800 border border-purple-200 ${padding}`}>
          <Globe size={iconSize} className="text-purple-600" />
          <span>{getDataStageLabel(stage)}</span>
        </span>
      );
    default:
      return <span>{stage}</span>;
  }
};

interface LayerBadgeProps {
  layer: ArchitectureLayer;
}

export const LayerBadge: React.FC<LayerBadgeProps> = ({ layer }) => {
  switch (layer) {
    case 'strategy':
      return (
        <span className="inline-flex items-center px-2 py-0.5 rounded text-[11px] font-semibold bg-[#B3101C]/10 text-[#B3101C] border border-[#B3101C]/20">
          STRATEGY LAYER • COMUNE
        </span>
      );
    case 'execution':
      return (
        <span className="inline-flex items-center px-2 py-0.5 rounded text-[11px] font-semibold bg-blue-50 text-blue-800 border border-blue-200">
          EXECUTION LAYER • ASTER / GESTORI
        </span>
      );
    case 'intelligence':
      return (
        <span className="inline-flex items-center px-2 py-0.5 rounded text-[11px] font-semibold bg-purple-50 text-purple-800 border border-purple-200">
          INTELLIGENCE LAYER • MANTOVA DIGITALE
        </span>
      );
  }
};
