import React, { useState } from 'react';
import {
  Database,
  Search,
  Filter,
  CheckCircle2,
  AlertTriangle,
  UserCheck,
  Shield,
  Layers,
  FileText,
  BarChart2,
  Info
} from 'lucide-react';
import { useData } from '../../store/DataContext';
import { DatasetEntity } from '../../types';

export const DataGovernanceView: React.FC = () => {
  const { data, searchQuery } = useData();
  const [search, setSearch] = useState('');
  const [selectedDomain, setSelectedDomain] = useState<string>('all');

  const domains = Array.from(new Set(data.datasets.map((d) => d.domain)));

  const filteredDatasets = data.datasets.filter((d) => {
    const effectiveSearch = (search || searchQuery).trim().toLowerCase();
    const matchSearch =
      effectiveSearch === '' ||
      d.name.toLowerCase().includes(effectiveSearch) ||
      d.responsibleOffice.toLowerCase().includes(effectiveSearch) ||
      d.sourceSystem.toLowerCase().includes(effectiveSearch);

    const matchDomain = selectedDomain === 'all' || d.domain === selectedDomain;
    return matchSearch && matchDomain;
  });

  const total = data.datasets.length;
  const withOwner = data.datasets.filter((d) => d.dataOwner !== null).length;
  const highQuality = data.datasets.filter((d) => d.dataQualityRating.startsWith('A')).length;
  const openDataCount = data.datasets.filter((d) => d.openDataAvailable).length;

  return (
    <div className="space-y-6">
      {/* Header Banner */}
      <div className="bg-white rounded-xl border border-stone-200 p-5 lg:p-6 shadow-xs">
        <div className="space-y-1">
          <div className="flex items-center gap-2">
            <span className="text-[10px] font-bold uppercase px-2 py-0.5 rounded bg-blue-50 text-blue-800 border border-blue-200">
              Asse 1 • Data Strategy
            </span>
            <span className="text-xs text-stone-500 font-medium">Piano Comunale di Data Governance (PRJ-02)</span>
          </div>
          <h2 className="text-xl sm:text-2xl font-bold text-[#242424] tracking-tight flex items-center gap-2">
            <Database size={22} className="text-[#B3101C]" />
            Data Governance — Censimento e Qualità del Patrimonio Informativo
          </h2>
          <p className="text-xs sm:text-sm text-stone-600 max-w-4xl leading-relaxed">
            Mappatura organica del patrimonio informativo del Comune di Mantova. Ogni base dati è associata a un <strong>Data Owner</strong> e a un <strong>Data Steward</strong>, valutata per qualità, classificazione di sicurezza e potenziale di interoperabilità per l'Urban Data Hub.
          </p>
        </div>

        {/* Metric Cards */}
        <div className="mt-5 pt-4 border-t border-stone-100 grid grid-cols-2 sm:grid-cols-4 gap-3 text-xs">
          <div className="bg-stone-50 p-3 rounded-lg border border-stone-200/70">
            <span className="text-stone-500 text-[10px] uppercase font-bold">Banche Dati Censite</span>
            <div className="text-xl font-bold text-stone-900 mt-0.5">{total} basi dati</div>
          </div>
          <div className="bg-stone-50 p-3 rounded-lg border border-stone-200/70">
            <span className="text-stone-500 text-[10px] uppercase font-bold">Con Data Owner Assegnato</span>
            <div className="text-xl font-bold text-blue-700 mt-0.5">{withOwner} su {total}</div>
          </div>
          <div className="bg-stone-50 p-3 rounded-lg border border-stone-200/70">
            <span className="text-stone-500 text-[10px] uppercase font-bold">Qualità Elevata (Rating A)</span>
            <div className="text-xl font-bold text-emerald-700 mt-0.5">{highQuality} su {total}</div>
          </div>
          <div className="bg-stone-50 p-3 rounded-lg border border-stone-200/70">
            <span className="text-stone-500 text-[10px] uppercase font-bold">Open Data Abilitabili</span>
            <div className="text-xl font-bold text-purple-700 mt-0.5">{openDataCount} dataset</div>
          </div>
        </div>
      </div>

      {/* Filter and Search Bar */}
      <div className="bg-white rounded-xl border border-stone-200 p-4 shadow-xs flex flex-col md:flex-row items-stretch md:items-center justify-between gap-3 text-xs">
        <div className="relative flex-1 max-w-md">
          <Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-stone-400" />
          <input
            type="text"
            placeholder="Cerca banca dati, ufficio, applicativo..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-full pl-9 pr-3 py-1.5 bg-stone-50 border border-stone-200 rounded-lg focus:outline-none focus:ring-1 focus:ring-[#B3101C] focus:bg-white"
          />
        </div>

        <div className="flex items-center gap-2">
          <span className="text-stone-500 font-medium">Dominio:</span>
          <select
            value={selectedDomain}
            onChange={(e) => setSelectedDomain(e.target.value)}
            className="bg-stone-50 border border-stone-200 rounded-lg px-2.5 py-1 text-xs font-semibold focus:outline-none"
          >
            <option value="all">Tutti i Domini ({total})</option>
            {domains.map((dom) => (
              <option key={dom} value={dom}>{dom}</option>
            ))}
          </select>
        </div>
      </div>

      {/* Dataset Cards Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {filteredDatasets.map((db) => (
          <div
            key={db.id}
            className="bg-white rounded-xl border border-stone-200 p-5 shadow-xs space-y-3 hover:border-stone-300 transition-all flex flex-col justify-between"
          >
            <div>
              <div className="flex items-start justify-between gap-2 pb-2.5 border-b border-stone-100">
                <div>
                  <div className="flex items-center gap-2">
                    <span className="font-bold text-xs px-2 py-0.5 rounded bg-stone-100 text-stone-800">
                      {db.id}
                    </span>
                    <span className="text-xs font-bold text-stone-600">{db.domain}</span>
                  </div>
                  <h3 className="font-bold text-base text-[#242424] mt-1.5">{db.name}</h3>
                </div>
                <span className={`px-2 py-0.5 rounded text-[10px] font-bold ${
                  db.dataQualityRating.startsWith('A') ? 'bg-emerald-100 text-emerald-800' :
                  db.dataQualityRating.startsWith('B') ? 'bg-blue-100 text-blue-800' : 'bg-amber-100 text-amber-800'
                }`}>
                  Rating: {db.dataQualityRating.split(' - ')[0]}
                </span>
              </div>

              <div className="mt-3 grid grid-cols-2 gap-2.5 p-3 bg-stone-50 rounded-lg border border-stone-200/60 text-xs">
                <div>
                  <span className="text-stone-500">Ufficio Responsabile:</span>
                  <div className="font-semibold text-stone-900 mt-0.5">{db.responsibleOffice}</div>
                </div>

                <div>
                  <span className="text-stone-500">Data Owner:</span>
                  <div className="font-semibold text-stone-900 mt-0.5">
                    {db.dataOwner || <em className="text-amber-800">Da formalizzare</em>}
                  </div>
                </div>

                <div>
                  <span className="text-stone-500">Sistema Sorgente:</span>
                  <div className="font-medium text-stone-800 mt-0.5">{db.sourceSystem}</div>
                </div>

                <div>
                  <span className="text-stone-500">Tipologia Archiviazione:</span>
                  <div className="font-medium text-stone-800 mt-0.5">{db.storageType}</div>
                </div>

                <div>
                  <span className="text-stone-500">Classificazione Sicurezza:</span>
                  <div className="font-semibold text-stone-900 mt-0.5">{db.classification}</div>
                </div>

                <div>
                  <span className="text-stone-500">Potenziale Interoperabilità:</span>
                  <div className="font-semibold text-stone-900 mt-0.5">{db.interoperabilityPotential}</div>
                </div>
              </div>
            </div>

            <div className="mt-4 pt-2.5 border-t border-stone-100 flex items-center justify-between text-[11px] text-stone-500">
              <span>Aggiornamento: {db.updateFrequency}</span>
              <span className={`px-2 py-0.5 rounded font-bold ${
                db.openDataAvailable ? 'bg-purple-100 text-purple-800' : 'bg-stone-100 text-stone-600'
              }`}>
                {db.openDataAvailable ? 'Open Data: Disponibile' : 'Dati Interni/GDPR'}
              </span>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

