import React, { useState } from 'react';
import {
  Gauge,
  CheckCircle2,
  AlertTriangle,
  ArrowRight,
  TrendingUp,
  FileText,
  SlidersHorizontal,
  Layers,
  Shield,
  Info
} from 'lucide-react';
import {
  ResponsiveContainer,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  Legend
} from 'recharts';
import { useData } from '../../store/DataContext';
import { DigitalMaturityDimension } from '../../types';
import { formatDate } from '../../utils';

export const MaturityAssessmentView: React.FC = () => {
  const { data, updateMaturityDimension } = useData();
  const [selectedDimension, setSelectedDimension] = useState<string | null>(null);

  const maturityLevels = [
    { level: 1, name: 'Iniziale', desc: 'Pratiche ad-hoc, iniziative frammentate, governance informale' },
    { level: 2, name: 'Definito', desc: 'Processi documentati, bozze di piano predisposte, ruoli in corso di formalizzazione' },
    { level: 3, name: 'Standardizzato', desc: 'Standard applicati sistematicamente, servizi digitalizzati di base a regime' },
    { level: 4, name: 'Avanzato', desc: 'Interoperabilità piena, monitoraggio continuo e integrazione tra dati e territorio' },
    { level: 5, name: 'Ottimizzato', desc: 'Capacità data-driven consolidata, miglioramento continuo e automazione responsabile' }
  ];

  const chartData = data.digitalMaturity.map((dim) => ({
    name: dim.dimensionName,
    shortName: dim.dimensionName.length > 15 ? dim.dimensionName.substring(0, 15) + '...' : dim.dimensionName,
    current: dim.currentLevel,
    target: dim.targetLevel,
    gap: dim.targetLevel - dim.currentLevel
  }));

  const avgCurrent = (
    data.digitalMaturity.reduce((sum, d) => sum + d.currentLevel, 0) / data.digitalMaturity.length
  ).toFixed(1);

  const avgTarget = (
    data.digitalMaturity.reduce((sum, d) => sum + d.targetLevel, 0) / data.digitalMaturity.length
  ).toFixed(1);

  const handleLevelChange = (id: string, newLevel: number) => {
    updateMaturityDimension(id, { currentLevel: newLevel });
  };

  return (
    <div className="space-y-6">
      {/* Header Banner */}
      <div className="bg-white rounded-xl border border-stone-200 p-5 lg:p-6 shadow-xs">
        <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
          <div className="space-y-1">
            <div className="flex items-center gap-2">
              <span className="text-[10px] font-bold uppercase px-2 py-0.5 rounded bg-emerald-50 text-emerald-800 border border-emerald-200">
                Modulo 6 • Strategic Assessment
              </span>
              <span className="text-xs text-stone-500 font-medium">12 Dimensioni di Analisi</span>
            </div>
            <h2 className="text-xl sm:text-2xl font-bold text-[#242424] tracking-tight flex items-center gap-2">
              <Gauge size={22} className="text-emerald-700" />
              Assessment della Maturità Digitale — Comune di Mantova
            </h2>
            <p className="text-xs sm:text-sm text-stone-600 max-w-4xl leading-relaxed">
              Quadro valutativo oggettivo basato su evidenze documentali e risultanze tecniche congiunte Comune / ASTER. La metodologia analizza 12 dimensioni chiave per misurare il divario (gap) tra lo stato attuale e i target del mandato 2027–2029.
            </p>
          </div>

          <div className="flex items-center gap-4 bg-stone-50 border border-stone-200 rounded-xl p-3 self-start lg:self-center text-xs">
            <div className="text-center">
              <div className="text-[10px] uppercase font-bold text-stone-500">Livello Attuale</div>
              <div className="text-xl font-bold text-[#B3101C] mt-0.5">{avgCurrent} / 5.0</div>
            </div>
            <div className="h-8 w-px bg-stone-200" />
            <div className="text-center">
              <div className="text-[10px] uppercase font-bold text-stone-500">Target di Mandato</div>
              <div className="text-xl font-bold text-emerald-700 mt-0.5">{avgTarget} / 5.0</div>
            </div>
          </div>
        </div>

        {/* Methodology Strip */}
        <div className="mt-5 pt-4 border-t border-stone-100">
          <h3 className="text-xs font-bold uppercase tracking-wider text-stone-500 mb-2">
            Scala dei Livelli di Maturità Metodologica (1–5)
          </h3>
          <div className="grid grid-cols-1 sm:grid-cols-5 gap-2 text-xs">
            {maturityLevels.map((lvl) => (
              <div key={lvl.level} className="p-2.5 rounded-lg bg-stone-50 border border-stone-200/70">
                <div className="flex items-center gap-1.5 font-bold text-stone-800">
                  <span className="w-4 h-4 rounded bg-stone-200 text-stone-800 text-[10px] flex items-center justify-center font-bold">
                    {lvl.level}
                  </span>
                  <span>{lvl.name}</span>
                </div>
                <div className="text-[10px] text-stone-500 mt-1 leading-snug">{lvl.desc}</div>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* COMPARATIVE CHART: CURRENT VS TARGET */}
      <div className="bg-white rounded-xl border border-stone-200 p-5 shadow-xs">
        <h3 className="font-bold text-sm text-[#242424] mb-1">
          Confronto Maturità Attuale vs Target 2029 per le 12 Dimensioni
        </h3>
        <p className="text-xs text-stone-500 mb-4">
          Visualizzazione del gap strategico da colmare con le azioni prioritarie del Piano Digitale
        </p>

        <div className="h-80">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={chartData} margin={{ top: 10, right: 20, left: 0, bottom: 40 }}>
              <XAxis dataKey="shortName" angle={-35} textAnchor="end" interval={0} tick={{ fontSize: 11 }} />
              <YAxis domain={[0, 5]} ticks={[1, 2, 3, 4, 5]} tick={{ fontSize: 11 }} />
              <Tooltip
                content={({ active, payload }) => {
                  if (active && payload && payload.length) {
                    const d = payload[0].payload;
                    return (
                      <div className="bg-stone-900 text-white p-3 rounded-lg text-xs shadow-elevated">
                        <div className="font-bold">{d.name}</div>
                        <div className="mt-1 text-stone-300">
                          Livello attuale: <span className="font-bold text-white">{d.current} / 5</span>
                        </div>
                        <div className="text-stone-300">
                          Target 2029: <span className="font-bold text-emerald-400">{d.target} / 5</span>
                        </div>
                        <div className="text-amber-300 font-semibold mt-1">
                          Gap da recuperare: +{d.gap} livelli
                        </div>
                      </div>
                    );
                  }
                  return null;
                }}
              />
              <Legend verticalAlign="top" height={36} />
              <Bar dataKey="current" name="Livello Attuale Rilevato" fill="#B3101C" radius={[4, 4, 0, 0]} />
              <Bar dataKey="target" name="Target di Mandato 2029" fill="#059669" radius={[4, 4, 0, 0]} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* 12 DIMENSIONS CARDS GRID */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {data.digitalMaturity.map((dim) => (
          <div
            key={dim.id}
            className="bg-white rounded-xl border border-stone-200 p-5 shadow-xs hover:border-stone-300 transition-all flex flex-col justify-between"
          >
            <div>
              {/* Header: Title and Levels */}
              <div className="flex items-start justify-between gap-2 pb-2.5 border-b border-stone-100">
                <div>
                  <span className="text-[10px] font-bold uppercase px-2 py-0.5 rounded bg-stone-100 text-stone-700">
                    {dim.code}
                  </span>
                  <h3 className="font-bold text-sm text-[#242424] mt-1">{dim.dimensionName}</h3>
                </div>
                <div className="text-right">
                  <div className="text-xs font-bold text-[#B3101C]">
                    Attuale: {dim.currentLevel} / 5
                  </div>
                  <div className="text-[11px] text-emerald-700 font-semibold">
                    Target: {dim.targetLevel} / 5
                  </div>
                </div>
              </div>

              <p className="text-xs text-stone-600 mt-2 leading-relaxed">{dim.description}</p>

              {/* Evidence criteria */}
              <div className="mt-3 p-3 bg-stone-50 rounded-lg border border-stone-200/60 space-y-2 text-xs">
                <div>
                  <span className="font-bold text-stone-800">Criteri ed Evidenze Rilevate:</span>
                  <ul className="list-disc list-inside text-stone-600 text-[11px] mt-1 space-y-0.5">
                    {dim.evidenceCriteria.map((ev, idx) => (
                      <li key={idx} className="line-clamp-2">{ev}</li>
                    ))}
                  </ul>
                </div>

                <div>
                  <span className="font-bold text-amber-900">Gap Identificati:</span>
                  <ul className="list-disc list-inside text-stone-600 text-[11px] mt-1 space-y-0.5">
                    {dim.identifiedGaps.map((gap, idx) => (
                      <li key={idx} className="line-clamp-2">{gap}</li>
                    ))}
                  </ul>
                </div>

                <div>
                  <span className="font-bold text-emerald-900">Azioni Prioritarie:</span>
                  <ul className="list-disc list-inside text-stone-600 text-[11px] mt-1 space-y-0.5">
                    {dim.priorityActions.map((act, idx) => (
                      <li key={idx} className="line-clamp-2">{act}</li>
                    ))}
                  </ul>
                </div>
              </div>
            </div>

            {/* Footer with evaluator and score slider */}
            <div className="mt-4 pt-3 border-t border-stone-100 space-y-2">
              <div className="flex items-center justify-between text-[11px] text-stone-500">
                <span>Rilevatore: {dim.evaluator}</span>
                <span>{formatDate(dim.assessmentDate)}</span>
              </div>

              <div className="flex items-center justify-between gap-2 pt-1">
                <span className="text-[11px] font-medium text-stone-600">Simula livello:</span>
                <div className="flex gap-1">
                  {[1, 2, 3, 4, 5].map((lvl) => (
                    <button
                      key={lvl}
                      onClick={() => handleLevelChange(dim.id, lvl)}
                      className={`w-6 h-6 rounded text-xs font-bold transition-all ${
                        dim.currentLevel === lvl
                          ? 'bg-[#B3101C] text-white shadow-xs'
                          : 'bg-stone-100 text-stone-700 hover:bg-stone-200'
                      }`}
                    >
                      {lvl}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

