import React, { useState } from 'react';
import {
  Briefcase,
  Search,
  Filter,
  FileText,
  Building,
  User,
  Calendar,
  DollarSign,
  AlertTriangle,
  CheckCircle2,
  ExternalLink,
  Target,
  Layers,
  ArrowUpRight,
  TrendingUp,
  SlidersHorizontal,
  Table as TableIcon,
  LayoutGrid
} from 'lucide-react';
import { useData } from '../../store/DataContext';
import { AsterIntervention, OperationalStatus } from '../../types';
import { StatusBadge, DataStageBadge } from '../../components/common/StatusBadge';
import { formatCurrency, formatPercent, formatDate } from '../../utils';

export const AsterPortfolioView: React.FC = () => {
  const { data, updateAsterIntervention, selectedLayer, setSelectedLayer, selectedYear, searchQuery } = useData();
  const [search, setSearch] = useState('');
  const [selectedServiceType, setSelectedServiceType] = useState<string>('all');
  const [viewMode, setViewMode] = useState<'grid' | 'table'>('grid');
  const [selectedIntervention, setSelectedIntervention] = useState<AsterIntervention | null>(null);

  const serviceTypes = [
    'Infrastrutture ICT',
    'GIS & Territorio',
    'IoT & Smart City',
    'Sviluppo & Integrazione',
    'Supporto & Monitoraggio'
  ];

  const filteredInterventions = data.asterInterventions.filter((item) => {
    // Year filter
    if (selectedYear !== 'all') {
      const matchYear = item.timeframe.includes(selectedYear) || (selectedYear === '2027' && item.updatedAt.startsWith('2027'));
      if (!matchYear) return false;
    }

    const effectiveSearch = (search || searchQuery).trim().toLowerCase();
    const matchSearch =
      effectiveSearch === '' ||
      item.name.toLowerCase().includes(effectiveSearch) ||
      item.code.toLowerCase().includes(effectiveSearch) ||
      item.entrustmentTitle.toLowerCase().includes(effectiveSearch) ||
      item.referenceAct.toLowerCase().includes(effectiveSearch) ||
      item.asterReferent.toLowerCase().includes(effectiveSearch);

    const matchType = selectedServiceType === 'all' || item.serviceType === selectedServiceType;
    return matchSearch && matchType;
  });

  return (
    <div className="space-y-6">
      {/* Header Banner */}
      <div className="bg-white rounded-xl border border-stone-200 p-5 lg:p-6 shadow-xs">
        <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
          <div className="space-y-1">
            <div className="flex items-center gap-2">
              <span className="text-[10px] font-bold uppercase px-2 py-0.5 rounded bg-blue-50 text-blue-800 border border-blue-200">
                Modulo 2 • Execution Layer
              </span>
              <span className="text-xs text-stone-500 font-medium">Società in house</span>
            </div>
            <h2 className="text-xl sm:text-2xl font-bold text-[#242424] tracking-tight flex items-center gap-2">
              <Briefcase size={22} className="text-blue-700" />
              ASTER — Portafoglio Interventi Operativi Affidati
            </h2>
            <p className="text-xs sm:text-sm text-stone-600 max-w-4xl leading-relaxed">
              Quadro organico delle attività operative, infrastrutturali e di presidio tecnologico delegate ad <strong>ASTER S.r.l. Unipersonale</strong> in virtù di convenzioni, contratti di servizio e disciplinari approvati. Il portafoglio operativo è distinto dagli indirizzi strategici comunali e ne traccia lo stato esecutivo reale.
            </p>
          </div>

          <div className="flex items-center gap-2 bg-stone-50 border border-stone-200 rounded-lg p-1 self-start lg:self-center">
            <button
              onClick={() => setViewMode('grid')}
              className={`p-1.5 rounded text-xs font-semibold flex items-center gap-1.5 transition-colors ${
                viewMode === 'grid' ? 'bg-white shadow-xs text-stone-900' : 'text-stone-500 hover:text-stone-900'
              }`}
              title="Vista schede dettagliate"
            >
              <LayoutGrid size={15} />
              <span className="hidden sm:inline">Schede</span>
            </button>
            <button
              onClick={() => setViewMode('table')}
              className={`p-1.5 rounded text-xs font-semibold flex items-center gap-1.5 transition-colors ${
                viewMode === 'table' ? 'bg-white shadow-xs text-stone-900' : 'text-stone-500 hover:text-stone-900'
              }`}
              title="Vista tabellare sintetica"
            >
              <TableIcon size={15} />
              <span className="hidden sm:inline">Tabella</span>
            </button>
          </div>
        </div>

        {/* Portfolio Summary Strip */}
        <div className="mt-5 pt-4 border-t border-stone-100 grid grid-cols-2 sm:grid-cols-4 gap-3 text-xs">
          <div className="bg-stone-50 p-2.5 rounded-lg border border-stone-200/70">
            <span className="text-[10px] uppercase font-bold text-stone-500">Totale Interventi</span>
            <div className="text-lg font-bold text-stone-900 mt-0.5">{data.asterInterventions.length}</div>
          </div>
          <div className="bg-stone-50 p-2.5 rounded-lg border border-stone-200/70">
            <span className="text-[10px] uppercase font-bold text-stone-500">Budget Annuale Tracciato</span>
            <div className="text-lg font-bold text-stone-900 mt-0.5">
              {formatCurrency(
                data.asterInterventions.reduce((sum, item) => sum + (item.budget || 0), 0)
              )}
            </div>
          </div>
          <div className="bg-stone-50 p-2.5 rounded-lg border border-stone-200/70">
            <span className="text-[10px] uppercase font-bold text-stone-500">Avanzamento Medio</span>
            <div className="text-lg font-bold text-blue-700 mt-0.5">
              {Math.round(
                data.asterInterventions.reduce((acc, curr) => acc + (curr.progressPercentage || 0), 0) /
                  data.asterInterventions.length
              )}
              %
            </div>
          </div>
          <div className="bg-stone-50 p-2.5 rounded-lg border border-stone-200/70">
            <span className="text-[10px] uppercase font-bold text-stone-500">Stato Rilevazione</span>
            <div className="text-lg font-bold text-emerald-700 mt-0.5">100% Verificato</div>
          </div>
        </div>
      </div>

      {/* Filter and Search Bar */}
      <div className="bg-white rounded-xl border border-stone-200 p-4 shadow-xs flex flex-col md:flex-row items-stretch md:items-center justify-between gap-3">
        <div className="relative flex-1 max-w-md">
          <Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-stone-400" />
          <input
            type="text"
            placeholder="Cerca per intervento, contratto, referente..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-full pl-9 pr-3 py-1.5 text-xs bg-stone-50 border border-stone-200 rounded-lg focus:outline-none focus:ring-1 focus:ring-blue-600 focus:bg-white"
          />
        </div>

        <div className="flex items-center gap-2 overflow-x-auto text-xs pb-1 md:pb-0">
          <span className="text-stone-500 font-medium whitespace-nowrap">Tipologia:</span>
          <button
            onClick={() => setSelectedServiceType('all')}
            className={`px-2.5 py-1 rounded-md font-medium whitespace-nowrap ${
              selectedServiceType === 'all'
                ? 'bg-blue-600 text-white'
                : 'bg-stone-100 text-stone-700 hover:bg-stone-200'
            }`}
          >
            Tutti ({data.asterInterventions.length})
          </button>
          {serviceTypes.map((type) => {
            const count = data.asterInterventions.filter((i) => i.serviceType === type).length;
            return (
              <button
                key={type}
                onClick={() => setSelectedServiceType(type)}
                className={`px-2.5 py-1 rounded-md font-medium whitespace-nowrap ${
                  selectedServiceType === type
                    ? 'bg-blue-600 text-white'
                    : 'bg-stone-100 text-stone-700 hover:bg-stone-200'
                }`}
              >
                {type} ({count})
              </button>
            );
          })}
        </div>
      </div>

      {/* Grid Mode */}
      {viewMode === 'grid' && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-5">
          {filteredInterventions.map((item) => (
            <div
              key={item.id}
              className="bg-white rounded-xl border border-stone-200 p-5 shadow-xs hover:border-blue-300 transition-all flex flex-col justify-between"
            >
              <div>
                {/* Header: ID, Tipologia, Stato Operativo */}
                <div className="flex items-start justify-between gap-2 pb-3 border-b border-stone-100">
                  <div className="space-y-0.5">
                    <div className="flex items-center gap-2">
                      <span className="font-bold text-xs px-2 py-0.5 rounded bg-blue-100 text-blue-900">
                        {item.code}
                      </span>
                      <span className="text-xs font-semibold text-stone-600">{item.serviceType}</span>
                    </div>
                    <h3 className="text-base font-bold text-stone-900 mt-1 leading-snug">
                      {item.name}
                    </h3>
                  </div>
                  <div className="flex flex-col items-end gap-1.5 shrink-0">
                    <StatusBadge status={item.operationalStatus} size="sm" />
                    <DataStageBadge stage={item.dataVerificationStage} size="sm" />
                  </div>
                </div>

                {/* Contracts and references */}
                <div className="mt-3 p-3 bg-stone-50 rounded-lg border border-stone-200/60 space-y-1.5 text-xs">
                  <div className="flex items-start gap-1.5 text-stone-700">
                    <FileText size={14} className="text-stone-400 shrink-0 mt-0.5" />
                    <span className="text-stone-500 font-medium">Affidamento:</span>
                    <span className="text-stone-900 font-semibold">{item.entrustmentTitle}</span>
                  </div>
                  <div className="text-[11px] text-stone-600 pl-5">
                    <span className="font-medium text-stone-700">Atto di riferimento:</span> {item.referenceAct}
                  </div>
                  <div className="grid grid-cols-2 gap-2 pt-1.5 border-t border-stone-200/50 text-[11px]">
                    <div>
                      <span className="text-stone-500">Ufficio Comunale Referente:</span>
                      <div className="font-semibold text-stone-800">{item.municipalReferentOffice}</div>
                    </div>
                    <div>
                      <span className="text-stone-500">Referente ASTER:</span>
                      <div className="font-semibold text-blue-900">{item.asterReferent}</div>
                    </div>
                  </div>
                </div>

                {/* Progress bar and Budget */}
                <div className="mt-4 grid grid-cols-2 gap-4 text-xs">
                  <div>
                    <div className="flex justify-between text-stone-600 mb-1">
                      <span>Avanzamento Operativo:</span>
                      <strong className="text-stone-900">{formatPercent(item.progressPercentage)}</strong>
                    </div>
                    <div className="w-full bg-stone-100 rounded-full h-2 overflow-hidden border border-stone-200">
                      <div
                        className="bg-blue-600 h-2 rounded-full"
                        style={{ width: `${item.progressPercentage || 0}%` }}
                      />
                    </div>
                  </div>
                  <div>
                    <div className="text-stone-500">Budget Annuale Convenzionato:</div>
                    <div className="text-sm font-bold text-stone-900 mt-0.5">{formatCurrency(item.budget)}</div>
                  </div>
                </div>

                {/* Activities & Deliverables */}
                <div className="mt-4 pt-3 border-t border-stone-100 space-y-2 text-xs">
                  <div>
                    <span className="font-bold text-stone-800">Attività Operative Principali:</span>
                    <ul className="list-disc list-inside text-stone-600 text-[11px] mt-1 space-y-0.5">
                      {item.plannedActivities.slice(0, 3).map((act, idx) => (
                        <li key={idx} className="line-clamp-1">{act}</li>
                      ))}
                    </ul>
                  </div>

                  <div>
                    <span className="font-bold text-stone-800">Deliverable Tracciati:</span>
                    <div className="flex flex-wrap gap-1.5 mt-1">
                      {item.deliverables.map((deliv, idx) => (
                        <span key={idx} className="px-2 py-0.5 bg-stone-100 text-stone-700 rounded text-[10px] font-medium border border-stone-200">
                          {deliv}
                        </span>
                      ))}
                    </div>
                  </div>

                  {/* Decision dependencies towards the municipality */}
                  {item.decisionDependencies && item.decisionDependencies.length > 0 && (
                    <div className="p-2.5 bg-amber-50 rounded-lg border border-amber-200 text-[11px] text-amber-950 mt-2">
                      <strong className="font-semibold flex items-center gap-1 text-amber-800">
                        <AlertTriangle size={13} /> Fabbisogno Decisionale verso il Comune:
                      </strong>
                      <span className="mt-0.5 block">{item.decisionDependencies[0]}</span>
                    </div>
                  )}
                </div>
              </div>

              {/* Card Footer: Strategic Linkages & Last Update */}
              <div className="mt-4 pt-3 border-t border-stone-100 flex items-center justify-between text-[11px] text-stone-500">
                <div className="flex items-center gap-2">
                  <span className="px-1.5 py-0.5 bg-red-50 text-[#B3101C] rounded font-semibold text-[10px]">
                    Goal {item.connectedStrategicGoal}
                  </span>
                  <span className="px-1.5 py-0.5 bg-stone-100 text-stone-700 rounded font-medium text-[10px]">
                    {item.connectedStrategicAxis}
                  </span>
                </div>
                <span>Aggiornato il {formatDate(item.updatedAt)}</span>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Table Mode */}
      {viewMode === 'table' && (
        <div className="bg-white rounded-xl border border-stone-200 overflow-hidden shadow-xs">
          <div className="overflow-x-auto">
            <table className="w-full text-left text-xs text-stone-700">
              <thead className="bg-stone-50 text-[11px] uppercase tracking-wider text-stone-500 font-semibold border-b border-stone-200">
                <tr>
                  <th className="py-3 px-3">Codice</th>
                  <th className="py-3 px-3">Intervento</th>
                  <th className="py-3 px-3">Tipologia</th>
                  <th className="py-3 px-3">Ufficio Referente</th>
                  <th className="py-3 px-3">Referente ASTER</th>
                  <th className="py-3 px-3">Budget</th>
                  <th className="py-3 px-3">Avanzamento</th>
                  <th className="py-3 px-3">Stato</th>
                  <th className="py-3 px-3">Validazione</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-stone-100">
                {filteredInterventions.map((item) => (
                  <tr key={item.id} className="hover:bg-stone-50/80 transition-colors">
                    <td className="py-3 px-3 font-bold text-blue-900">{item.code}</td>
                    <td className="py-3 px-3">
                      <div className="font-semibold text-stone-900">{item.name}</div>
                      <div className="text-[11px] text-stone-500 line-clamp-1">{item.entrustmentTitle}</div>
                    </td>
                    <td className="py-3 px-3 whitespace-nowrap">{item.serviceType}</td>
                    <td className="py-3 px-3 whitespace-nowrap text-stone-600">{item.municipalReferentOffice}</td>
                    <td className="py-3 px-3 whitespace-nowrap font-medium text-stone-800">{item.asterReferent}</td>
                    <td className="py-3 px-3 whitespace-nowrap font-semibold">{formatCurrency(item.budget)}</td>
                    <td className="py-3 px-3 whitespace-nowrap">
                      <span className="font-bold text-stone-900">{formatPercent(item.progressPercentage)}</span>
                    </td>
                    <td className="py-3 px-3 whitespace-nowrap">
                      <StatusBadge status={item.operationalStatus} size="sm" />
                    </td>
                    <td className="py-3 px-3 whitespace-nowrap">
                      <DataStageBadge stage={item.dataVerificationStage} size="sm" />
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
};

